-- public.worker_learn_paced(p_world uuid, p_id integer, p_skill text, p_base double precision, p_pace double precision)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.worker_learn_paced(p_world uuid, p_id integer, p_skill text, p_base double precision, p_pace double precision)
 RETURNS double precision
 LANGUAGE plpgsql
AS $function$
declare c creature; was double precision; now_v double precision; c2 creature;
begin
  select * into c from creature where world_id = p_world and id = p_id;
  if not found then return 0; end if;
  was := coalesce((c.skills->>p_skill)::double precision, 1);
  -- Its level skill at what its trade's goes are worth against every other trade's (`learn_pace`).
  now_v := least(100, was + skill_gain_of(was, p_base * beast_mul(c, 'learn') * coalesce(p_pace, learn_pace(c, p_skill)), 0.6 + 0.8 * random()));
  update creature set skills = jsonb_set(skills, array[p_skill], to_jsonb(now_v)), xp = xp + (now_v - was),
      ledger = case when c.mode = 'deed' and now_v > was
                    then ledger_add(ledger, island_day(p_world), 0, now_v - was, null, 0) else ledger end
    where world_id = p_world and id = p_id;
  select * into c2 from creature where world_id = p_world and id = p_id;
  if stage_of(c2) > stage_of(c) then
    update creature set health = health * stage_mul_hardy(),
        -- And one nobody has named is called what it has become (`kind_named`).
        name = case when kind_named(c) then kind_name_at(c2) else name end
      where world_id = p_world and id = p_id;
    -- And a trait for each slot the stage opens (`stage_slots`), by its keeper's husbandry (`open_slots`).
    perform open_slots(p_world, p_id, stage_of(c), stage_of(c2), keeper_husbandry(p_world, c));
    if c.mode <> 'wild' and c.keeper is not null then
      -- Each stage it reached, for the journal.
      perform journal_note(p_world, c.keeper, 'evolved:' || st) from generate_series(stage_of(c) + 1, stage_of(c2)) st;
      perform wtell(p_world, c.keeper, c.name || ' evolved: '
        || (select sd.stages[stage_of(c2)] from species_def sd where sd.id = c.species) || '.', 'event');
    end if;
  end if;
  return now_v - was;
end $function$
